import ghidra.app.script.GhidraScript;import ghidra.program.model.symbol.*;import ghidra.program.model.listing.*;import ghidra.program.model.address.*;import java.io.*;
public class UpdateClasses extends GhidraScript {public void run()throws Exception{PrintWriter w=new PrintWriter(getScriptArgs()[0]);SymbolIterator si=currentProgram.getSymbolTable().getAllSymbols(true);while(si.hasNext()){Symbol s=si.next();if(!s.getName().equals("vftable")||!s.getName(true).matches(".*(UpdateEngine|FirmwareService).*"))continue;w.println("VTABLE "+s.getAddress()+" "+s.getName(true));for(Reference r:getReferencesTo(s.getAddress())){Function f=getFunctionContaining(r.getFromAddress());w.println(" XREF "+r.getFromAddress()+" "+(f==null?"":f.getEntryPoint()+" "+f.getName()));}for(int n=0;n<48;n++){Address a=s.getAddress().add(4*n);Address dest=toAddr(Integer.toUnsignedLong(currentProgram.getMemory().getInt(a)));Function f=getFunctionAt(dest);if(f==null)break;w.println(" SLOT "+Integer.toHexString(4*n)+" "+dest+" "+f.getName());}}w.close();}}
